// DeleteUniqueIndexCache 删除索引存在的缓存
func (n *NpsSummaryRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.NpsSummary) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, n.cache.Key(CacheNpsSummaryByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[n.cache.Key(CacheNpsSummaryByIDPrefix, item.ID)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpsSummaryByStartTimeEndTimePrefix, item.StartTime, item.EndTime)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpsSummaryByStartTimePrefix, item.StartTime)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := n.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
